# -*- coding: utf-8 -*-
# Catechism bank — Molla Jāmī's Q&A on the Kāfiya, part 3: the marfūʿāt, items 56–80.
ITEMS = [
 {"n": 56, "q": {"tr": "«Merfûât» ne kelimedir? Merfûâtın tarifi nedir? Fâiliyyet alâmetleri nelerdir?", "en": "What kind of word is «marfūʿāt», how are the marfūʿāt defined, and what are the signs of doer-ness?"},
  "a": {"tr": "مَرْفُوع kelimesinin cem'idir; mevsûfu müzekker gayr-i âkil olan sıfatlar elif ve tâ ile cem'lenir. Tarifi: fâiliyyet alâmetine şâmil olandır. Fâiliyyet alâmetleri: zamme, vâv, elif.", "en": "The plural of مَرْفُوع — adjectives whose described noun is masculine and non-rational take the alif-tāʾ plural. Definition: what carries the sign of doer-ness. The signs: ḍamma, wāw, alif."},
  "ar": ["مَا اشْتَمَلَ عَلَى عَلَمِ الْفَاعِلِيَّةِ"], "notes": ["al-marfuat-al-fail-wa-naibuh", "tarifat-daftar-al-kafiya"]},
 {"n": 57, "q": {"tr": "Fâil nedir? Fiilin fâil ile kıyam ciheti ne demektir?", "en": "What is the doer, and what does «the verb's standing by it» mean?"},
  "a": {"tr": "Fâil: fiilin veya şibh-i fiilin, kendisiyle kıyamı cihetine binaen kendisi üzerine takdim olunduğu ve kendisine isnad olunduğu isimdir (قَامَ زَيْدٌ؛ زَيْدٌ قَائِمٌ أَبُوهُ). Fiilin fâil ile kıyam ciheti: fiilin malum sîga veya malum sîga hükmü üzere olmasıdır.", "en": "The noun to which a verb or verb-like word, put before it, is predicated, on the side of the act's standing by it (قَامَ زَيْدٌ؛ زَيْدٌ قَائِمٌ أَبُوهُ). «Standing by it»: the verb being active in form or in ruling."},
  "ar": ["مَا أُسْنِدَ إِلَيْهِ الْفِعْلُ أَوْ شِبْهُهُ وَقُدِّمَ عَلَيْهِ عَلَى جِهَةِ قِيَامِهِ بِهِ", "زَيْدٌ قَائِمٌ أَبُوهُ"], "notes": ["fail", "al-marfuat-al-fail-wa-naibuh"]},
 {"n": 58, "q": {"tr": "Fâilde asıl olan nedir? ضَرَبَ غُلَامَهُ زَيْدٌ ve ضَرَبَ غُلَامُهُ زَيْدًا câiz midir?", "en": "What is the doer's root position? Are ضَرَبَ غُلَامَهُ زَيْدٌ and ضَرَبَ غُلَامُهُ زَيْدًا allowed?"},
  "a": {"tr": "Fâilde asıl olan fiili takip etmektir. ضَرَبَ غُلَامَهُ زَيْدٌ câizdir: zamirin mercii olan زَيْد fâil olmakla rütbeten mukaddem olduğundan yalnız lafzan izmâr kable'z-zikr vardır, bu câizdir. ضَرَبَ غُلَامُهُ زَيْدًا câiz değildir: mercî mef'ûl olmakla hem lafzan hem rütbeten izmâr kable'z-zikr vardır.", "en": "To follow its verb. ضَرَبَ غُلَامَهُ زَيْدٌ is allowed: Zayd, the pronoun's referent, comes first in rank as doer, so the pronoun precedes it in wording only. ضَرَبَ غُلَامُهُ زَيْدًا is not: the referent is the object, so the pronoun precedes it both in wording and in rank."},
  "ar": ["ضَرَبَ غُلَامَهُ زَيْدٌ"], "notes": ["fail", "tanazu"]},
 {"n": 59, "q": {"tr": "Hem lafzan hem rütbeten izmâr kable'z-zikre cevaz veren var mıdır? Delilleri nedir?", "en": "Does anyone allow a pronoun before its referent in both wording and rank, and what is the proof?"},
  "a": {"tr": "Ahfeş ve İbn Cinnî câiz görmüş ve şu şiiri delil getirmişlerdir: جَزَى رَبُّهُ عَنِّي عَدِيَّ بْنَ حَاتِمٍ • جَزَاءَ الْكِلَابِ الْعَاوِيَاتِ وَقَدْ فَعَلْ — رَبُّهُ'de hem lafzan hem rütbeten izmâr kable'z-zikr vardır. (Buna, رَبُّهُ «رَبُّ الْجَزَاءِ» takdirinde olmakla izmâr kable'z-zikr yoktur diye cevap verilmiştir.)", "en": "Al-Akhfash and Ibn Jinnī allowed it, citing جَزَى رَبُّهُ عَنِّي عَدِيَّ بْنَ حَاتِمٍ • جَزَاءَ الْكِلَابِ الْعَاوِيَاتِ وَقَدْ فَعَلْ, where رَبُّهُ precedes its referent in both. (It was answered that رَبُّهُ means «the Lord of the requital», so there is no such precedence.)"},
  "ar": ["جَزَى رَبُّهُ عَنِّي عَدِيَّ بْنَ حَاتِمٍ"], "notes": ["fail"]},
 {"n": 60, "q": {"tr": "Fâilin takdiminin vâcib olduğu yerler nerelerdir? Niçin?", "en": "Where must the doer precede the object, and why?"},
  "a": {"tr": "Lafzî i'rab bulunmayıp karine de olmadığında, iltibastan kaçınmak için (ضَرَبَ مُوسَى عِيسَى); fâil fiile muttasıl zamir olduğunda, ittisal infisale zıt olduğundan (ضَرَبْتُ زَيْدًا); mef'ûl إِلَّا'dan sonra vâki olduğunda, matlub olan hasr değişmesin diye (مَا ضَرَبَ زَيْدٌ إِلَّا عَمْرًا); mef'ûl إِلَّا mânâsına olan kelimeden sonra vâki olduğunda (إِنَّمَا ضَرَبَ زَيْدٌ عَمْرًا).", "en": "When no iʿrāb or clue shows which is which, to avoid confusion (ضَرَبَ مُوسَى عِيسَى); when the doer is a pronoun attached to the verb, attachment excluding separation (ضَرَبْتُ زَيْدًا); when the object follows إِلَّا, lest the intended restriction change (مَا ضَرَبَ زَيْدٌ إِلَّا عَمْرًا); and when it follows a word in the sense of إِلَّا (إِنَّمَا ضَرَبَ زَيْدٌ عَمْرًا)."},
  "ar": ["ضَرَبَ مُوسَى عِيسَى", "مَا ضَرَبَ زَيْدٌ إِلَّا عَمْرًا"], "notes": ["fail", "tanazu"]},
 {"n": 61, "q": {"tr": "Fâilin te'hirinin vâcib olduğu yerler nerelerdir? Niçin?", "en": "Where must the doer follow the object, and why?"},
  "a": {"tr": "Fâile mef'ûlün zamiri muttasıl olduğunda, lafzan ve rütbeten izmâr kable'z-zikr lâzım gelmesin diye (ضَرَبَ زَيْدًا غُلَامُهُ); fâil إِلَّا'dan sonra vâki olduğunda (مَا ضَرَبَ عَمْرًا إِلَّا زَيْدٌ); fâil إِلَّا mânâsına kelimeden sonra vâki olduğunda (إِنَّمَا ضَرَبَ عَمْرًا زَيْدٌ); mef'ûl fiile muttasıl zamir olup fâil olmadığında (ضَرَبَكَ زَيْدٌ).", "en": "When the object's pronoun is attached to the doer, lest the pronoun precede its referent in wording and rank (ضَرَبَ زَيْدًا غُلَامُهُ); when the doer follows إِلَّا (مَا ضَرَبَ عَمْرًا إِلَّا زَيْدٌ); when it follows a word in the sense of إِلَّا (إِنَّمَا ضَرَبَ عَمْرًا زَيْدٌ); and when the object, not the doer, is a pronoun attached to the verb (ضَرَبَكَ زَيْدٌ)."},
  "ar": ["ضَرَبَ زَيْدًا غُلَامُهُ", "ضَرَبَكَ زَيْدٌ"], "notes": ["fail", "tanazu"]},
 {"n": 62, "q": {"tr": "Fâilin fiilinin hazfi kaç şekilde olur?", "en": "In how many ways is the doer's verb dropped?"},
  "a": {"tr": "Karine kâim olduğunda cevâzen veya vücûben. Cevâzen hazif iki şekilde: muhakkak sual karinesiyle («مَنْ قَامَ؟» sualine «زَيْدٌ» cevabı); mukadder sual karinesiyle (لِيُبْكَ يَزِيدُ ضَارِعٌ لِخُصُومَةٍ • وَمُخْتَبِطٌ مِمَّا تُطِيحُ الطَّوَائِحُ — يَبْكِيهِ fiili hazfolunmuştur; hazfe karine bir fiilin iki fâilinin olması, mahzufun tayinine karine mukadder مَنْ يَبْكِيهِ sualidir). Vücûben hazfe misal: وَإِنْ أَحَدٌ مِنَ الْمُشْرِكِينَ اسْتَجَارَكَ — أَحَدٌ'un fiili vücûben hazfolunmuştur; hazfe karine إِنْ'in isim üzerine girmesi, tayinine karine müfessir olan ikinci اسْتَجَارَكَ'dir.", "en": "Optionally or necessarily, given a clue. Optionally in two ways: by an actual question («مَنْ قَامَ؟» answered «زَيْدٌ»); by an implied question (لِيُبْكَ يَزِيدُ ضَارِعٌ لِخُصُومَةٍ • وَمُخْتَبِطٌ مِمَّا تُطِيحُ الطَّوَائِحُ — يَبْكِيهِ dropped; the clue to the dropping, one verb with two doers; to what was dropped, the implied مَنْ يَبْكِيهِ). Necessarily: وَإِنْ أَحَدٌ مِنَ الْمُشْرِكِينَ اسْتَجَارَكَ — the verb of أَحَدٌ dropped; the clue, إِنْ entering upon a noun; the identity, the explaining second اسْتَجَارَكَ."},
  "ar": ["وَإِنْ أَحَدٌ مِنَ الْمُشْرِكِينَ اسْتَجَارَكَ"], "notes": ["hadhf-wa-taqdir", "fail"]},
 {"n": 63, "q": {"tr": "Tenâzu' nedir? Basralılar ve Kûfelilerin ihtiyarı nedir?", "en": "What is tanāzuʿ, and what do the Baṣrans and Kūfans prefer?"},
  "a": {"tr": "Tenâzu': iki fiilin, kendilerinden sonra gelen ism-i zâhiri almak için çekişmeleridir — fâiliyyette (ضَرَبَنِي وَأَكْرَمَنِي زَيْدٌ), mef'ûliyyette (ضَرَبْتُ وَأَكْرَمْتُ زَيْدًا), muhtelif (ضَرَبَنِي وَأَكْرَمْتُ زَيْدًا). Basralılar ikinci fiili amel ettirir: ism-i zâhire daha yakındır, fiil ile isim arası yabancı bir kelime ile ayrılmasın ve istimalde çoktur. Kûfeliler birinciyi: takaddüm etmiştir ve izmâr kable'z-zikr lâzım gelmesin. İkinci amel ederse birinci fiil fâil iktizâ ediyorsa altına ism-i zâhire muvâfık zamir kılınır, mef'ûl iktizâ edip müstağnî ise hazfolunur, değilse izhar edilir. Birinci amel ederse ikinci fiil fâil iktizâ ediyorsa altına zamir kılınır, mef'ûl iktizâ ediyorsa mâni yoksa zamir, varsa ism-i zâhir getirilir.", "en": "Two verbs contending for the overt noun after them — in doer-ness (ضَرَبَنِي وَأَكْرَمَنِي زَيْدٌ), object-ness (ضَرَبْتُ وَأَكْرَمْتُ زَيْدًا) or mixed (ضَرَبَنِي وَأَكْرَمْتُ زَيْدًا). The Baṣrans let the second govern: it is nearer, nothing foreign then parts verb and noun, and usage favours it. The Kūfans the first: it came first, and no pronoun then precedes its referent. If the second governs, the first takes a hidden doer agreeing with the noun, and its object is dropped if dispensable, else shown; if the first governs, the second takes a hidden doer, or a pronoun object where nothing forbids, else the overt noun."},
  "ar": ["ضَرَبَنِي وَأَكْرَمَنِي زَيْدٌ", "ضَرَبْتُ وَأَكْرَمْتُ زَيْدًا"], "notes": ["tanazu"]},
 {"n": 64, "q": {"tr": "كَفَانِي وَلَمْ أَطْلُبْ قَلِيلٌ مِنَ الْمَالِ şiirinin tamamı nasıldır ve nüktesi nedir?", "en": "What is the whole of the verse كَفَانِي وَلَمْ أَطْلُبْ قَلِيلٌ مِنَ الْمَالِ, and what is its point?"},
  "a": {"tr": "وَلَوْ أَنَّمَا أَسْعَى لِأَدْنَى مَعِيشَةٍ • كَفَانِي وَلَمْ أَطْلُبْ قَلِيلٌ مِنَ الْمَالِ / وَلَكِنَّمَا أَسْعَى لِمَجْدٍ مُؤَثَّلٍ • وَقَدْ يُدْرِكُ الْمَجْدَ الْمُؤَثَّلَ أَمْثَالِي. Kûfeliler bu şiiri, كَفَانِي ve لَمْ أَطْلُبْ'un قَلِيلٌ مِنَ الْمَالِ'de tenâzu edip İmruülkays'ın birinci fiili amel ettirmesine delil getirmişlerdir. Musannife göre iki fiilin de ona yönelmesi takdirinde mânâ fâsid olduğundan şiir tenâzu bâbından değildir; لَمْ أَطْلُبْ'un mef'ûlü mahzuf الْعِزَّ وَالْمَجْدَ'dir.", "en": "وَلَوْ أَنَّمَا أَسْعَى لِأَدْنَى مَعِيشَةٍ • كَفَانِي وَلَمْ أَطْلُبْ قَلِيلٌ مِنَ الْمَالِ / وَلَكِنَّمَا أَسْعَى لِمَجْدٍ مُؤَثَّلٍ • وَقَدْ يُدْرِكُ الْمَجْدَ الْمُؤَثَّلَ أَمْثَالِي. The Kūfans cite it: the two verbs contend for قَلِيلٌ مِنَ الْمَالِ and Imruʾ al-Qays let the first govern. For the author it is no tanāzuʿ at all, the sense being corrupt if both verbs aimed at it; the object of لَمْ أَطْلُبْ is a dropped الْعِزَّ وَالْمَجْدَ."},
  "ar": ["كَفَانِي وَلَمْ أَطْلُبْ قَلِيلٌ مِنَ الْمَالِ"], "notes": ["tanazu"]},
 {"n": 65, "q": {"tr": "Nâib-i fâil nedir? Şartı nedir?", "en": "What is the deputy doer, and what is its condition?"},
  "a": {"tr": "Fâili hazfolunup kendisi fâilin makamına ikame olunan her mef'ûldür. Şartı: fiilin meçhul sîga üzere olmasıdır (mâzîde فُعِلَ, muzâride يُفْعَلُ).", "en": "Any object whose doer is dropped and which is set in the doer's place. Its condition: the verb in passive form (فُعِلَ in the past, يُفْعَلُ in the present)."},
  "ar": ["كُلُّ مَفْعُولٍ حُذِفَ فَاعِلُهُ وَأُقِيمَ هُوَ مَقَامَهُ"], "notes": ["naib-al-fail", "al-marfuat-al-fail-wa-naibuh"]},
 {"n": 66, "q": {"tr": "Nâib-i fâil vâki olmayan mef'ûller nelerdir? Niçin?", "en": "Which objects can never be the deputy doer, and why?"},
  "a": {"tr": "عَلِمْتُ bâbının ikinci ve أَعْلَمْتُ bâbının üçüncü mef'ûlü: aynı anda hem müsned hem müsnedün ileyh olması lâzım gelir. Lâmsız mef'ûl leh: ref' nâib-i fâil alâmetidir ve ref' gelince kelimenin önceden mef'ûl leh olduğuna delâlet eden karine kalmaz (lâmlı mef'ûl leh olabilir: baştaki lâm karinedir). Mef'ûl maah, vâvlı veya vâvsız: vâvlısı — vâv aslında atıf harfi olup infisâle delâlet eder, nâib-i fâil ise fiilden bir cüz gibidir; vâvsızı — ref' gelince mef'ûl maah olduğuna delâlet eden karine kalmaz.", "en": "The second object of عَلِمْتُ and the third of أَعْلَمْتُ: each would be predicate and subject at once. The lām-less mafʿūl lahu: rafʿ marks the deputy, and once it comes nothing shows the word was a mafʿūl lahu (with the lām it may: the lām is the clue). The mafʿūl maʿah, with the wāw or without: with it, the wāw is at root a conjunction and marks separateness while the deputy is like a part of the verb; without it, nothing shows what it was."},
  "ar": ["نَائِبُ الْفَاعِلِ"], "notes": ["naib-al-fail", "mafulayn"]},
 {"n": 67, "q": {"tr": "Mübtedânın tarifi nedir? Misalleri nelerdir? Mübtedâda ne zaman iki emir câiz olur?", "en": "How is the mubtadaʾ defined, what are its examples, and when are two readings allowed?"},
  "a": {"tr": "Müsnedün ileyh olduğu hâlde lafzî âmillerden soyulan isim, veya zâhirî fâilini ref' edici olduğu hâlde istifham elifi veya nefiy harfinden sonra vâki olan sıfattır (زَيْدٌ قَائِمٌ؛ أَقَائِمٌ الزَّيْدَانِ). Sıfat olan mübtedâ müfred isme mutâbakat ederse iki emir câizdir: sıfatın mübtedâ olup mâba'dinin haber makamına kâim fâil olması, veya sıfatın mukaddem haber olup mâba'dinin muahhar mübtedâ olması (مَا قَائِمٌ زَيْدٌ، أَقَائِمٌ زَيْدٌ). أَقَائِمَانِ الزَّيْدَانِ'da أَقَائِمَانِ mukaddem haberdir; أَقَائِمٌ الزَّيْدَانِ'da أَقَائِمٌ mübtedâ, الزَّيْدَانِ haber makamına kâim fâildir.", "en": "The noun stripped of wording governors as subject, or the adjective after the question hamza or a negation raising an overt doer (زَيْدٌ قَائِمٌ؛ أَقَائِمٌ الزَّيْدَانِ). When the adjectival mubtadaʾ agrees with a singular noun, two readings are allowed: adjective as mubtadaʾ with the noun its doer standing for the khabar, or adjective as fronted khabar with the noun a delayed mubtadaʾ (مَا قَائِمٌ زَيْدٌ، أَقَائِمٌ زَيْدٌ). In أَقَائِمَانِ الزَّيْدَانِ the first word is a fronted khabar; in أَقَائِمٌ الزَّيْدَانِ it is the mubtadaʾ and الزَّيْدَانِ its doer in the khabar's place."},
  "ar": ["هُوَ الِاسْمُ الْمُجَرَّدُ عَنِ الْعَوَامِلِ اللَّفْظِيَّةِ مُسْنَدًا إِلَيْهِ أَوِ الصِّفَةُ الْوَاقِعَةُ بَعْدَ حَرْفِ النَّفْيِ وَأَلِفِ الِاسْتِفْهَامِ رَافِعَةً لِظَاهِرٍ", "أَقَائِمٌ الزَّيْدَانِ"], "notes": ["mubtada-khabar", "al-mubtada-wa-nawah"]},
 {"n": 68, "q": {"tr": "Haberin tarifi nedir? Mübtedâ ve haberde âmil nedir?", "en": "How is the khabar defined, and what governs the mubtadaʾ and the khabar?"},
  "a": {"tr": "Haber: mezkûr sıfata mugâyir, müsned bih olup lafzî âmillerden soyulan isimdir. Âmil, Basralılara göre âmil-i mânevîdir (ibtidâiyyet mânâsı: ismin lafzî âmillerden mücerred olması); Sîbeveyh'e göre mübtedâda âmil-i mânevî, haberde mübtedâ; Kûfelilere göre mübtedâ haberde, haber mübtedâda âmildir.", "en": "The noun stripped of wording governors that is predicated, other than the adjective just mentioned. The governor, for the Baṣrans, is one of meaning — inception, the noun's bareness of wording governors; for Sībawayh, that for the mubtadaʾ and the mubtadaʾ itself for the khabar; for the Kūfans, each governs the other."},
  "ar": ["هُوَ الْمُجَرَّدُ الْمُسْنَدُ بِهِ الْمُغَايِرُ لِلصِّفَةِ الْمَذْكُورَةِ"], "notes": ["mubtada-khabar", "al-amil-al-manawi"]},
 {"n": 69, "q": {"tr": "Mübtedâda asıl olan nedir? فِي دَارِهِ زَيْدٌ ve صَاحِبُهَا فِي الدَّارِ câiz midir?", "en": "What is the mubtadaʾ's root position? Are فِي دَارِهِ زَيْدٌ and صَاحِبُهَا فِي الدَّارِ allowed?"},
  "a": {"tr": "Haber üzerine takdimdir. فِي دَارِهِ زَيْدٌ câizdir: yalnız lafzan izmâr kable'z-zikr vardır. صَاحِبُهَا فِي الدَّارِ câiz değildir: hem lafzan hem rütbeten izmâr kable'z-zikr vardır.", "en": "To precede the khabar. فِي دَارِهِ زَيْدٌ is allowed, the pronoun preceding its referent in wording only; صَاحِبُهَا فِي الدَّارِ is not, preceding it in wording and in rank."},
  "ar": ["فِي دَارِهِ زَيْدٌ"], "notes": ["mubtada-khabar", "taqdim-al-musnad"]},
 {"n": 70, "q": {"tr": "Mübtedâ nekre olur mu? Tahsis vecihleri nelerdir?", "en": "Can the mubtadaʾ be indefinite, and what are the ways of particularising it?"},
  "a": {"tr": "Aslı ma'rife olmak ise de tahsis vecihlerinden biriyle hususîleşen nekre mübtedâ olabilir: sıfatla (وَلَعَبْدٌ مُؤْمِنٌ خَيْرٌ مِنْ مُشْرِكٍ); mütekellimin ilmiyle (أَرَجُلٌ فِي الدَّارِ أَمِ امْرَأَةٌ); nefiy hayyizinde vâki olmakla (مَا أَحَدٌ خَيْرٌ مِنْكَ); fâilin hususîleştiği şeyle (شَرٌّ أَهَرَّ ذَا نَابٍ); zarf olan haberin takdimiyle (فِي الدَّارِ رَجُلٌ); mütekellime nisbetle (سَلَامٌ عَلَيْكَ, aslı سَلَامِي عَلَيْكَ).", "en": "Its root is definiteness, but an indefinite made particular may serve: by an adjective (وَلَعَبْدٌ مُؤْمِنٌ خَيْرٌ مِنْ مُشْرِكٍ); by the speaker's knowledge (أَرَجُلٌ فِي الدَّارِ أَمِ امْرَأَةٌ); by standing under negation (مَا أَحَدٌ خَيْرٌ مِنْكَ); by what particularises its doer (شَرٌّ أَهَرَّ ذَا نَابٍ); by a fronted ẓarf khabar (فِي الدَّارِ رَجُلٌ); by relation to the speaker (سَلَامٌ عَلَيْكَ, from سَلَامِي عَلَيْكَ)."},
  "ar": ["وَلَعَبْدٌ مُؤْمِنٌ خَيْرٌ مِنْ مُشْرِكٍ", "شَرٌّ أَهَرَّ ذَا نَابٍ"], "notes": ["al-mubtada-wa-nawah", "tankir-al-musnad-ilayh"]},
 {"n": 71, "q": {"tr": "Mübtedânın haberi cümle olduğu zaman ne lâzım gelir?", "en": "What is required when the khabar is a sentence?"},
  "a": {"tr": "Bir âid lâzım gelir: ya zamir (زَيْدٌ قَائِمٌ أَبُوهُ), ya lâm-ı ta'rif (نِعْمَ الرَّجُلُ زَيْدٌ), ya zamir mevziinde ism-i zâhir (الْحَاقَّةُ مَا الْحَاقَّةُ), ya haberin mübtedâ için tefsir olması (قُلْ هُوَ اللهُ أَحَدٌ). Âid zamir ise karine kâim olduğunda hazfi câizdir (الْبُرُّ الْكُرُّ بِسِتِّينَ دِرْهَمًا — مِنْهُ hazfolunmuştur).", "en": "A returner: a pronoun (زَيْدٌ قَائِمٌ أَبُوهُ), the article (نِعْمَ الرَّجُلُ زَيْدٌ), an overt noun in the pronoun's place (الْحَاقَّةُ مَا الْحَاقَّةُ), or the khabar's being an explanation of the mubtadaʾ (قُلْ هُوَ اللهُ أَحَدٌ). A pronoun returner may be dropped with a clue (الْبُرُّ الْكُرُّ بِسِتِّينَ دِرْهَمًا, with مِنْهُ dropped)."},
  "ar": ["الْحَاقَّةُ مَا الْحَاقَّةُ", "قُلْ هُوَ اللهُ أَحَدٌ"], "notes": ["khabar-al-mubtada-wa-ahkamuh", "anwa-al-khabar"]},
 {"n": 72, "q": {"tr": "Zarf (zarf-ı zaman, zarf-ı mekân veya câr-mecrûr) vâki olan haber cümle midir, müfred midir?", "en": "Is a ẓarf khabar — a time or place adverb or a jarr phrase — a sentence or a single word?"},
  "a": {"tr": "Ekser nahivcilere (Basralılar) göre fiil takdiriyle cümledir: zarflara âmil olan bir müteallak lâzımdır, amelde asıl olan fiildir. Azına (Kûfeliler) göre ism-i fâil takdiriyle müfreddir: bu zarf haberdir, haberde asıl olan müfred olmaktır.", "en": "For most (the Baṣrans), a sentence with a verb implied — ẓarfs need a governor to hang on, and the root governor is the verb. For a few (the Kūfans), a single word with an ism fāʿil implied — it is a khabar, and the khabar's root is to be single."},
  "ar": ["زَيْدٌ فِي الدَّارِ"], "notes": ["zarf-mustaqarr-wa-laghw", "anwa-al-khabar"]},
 {"n": 73, "q": {"tr": "Mübtedânın haber üzerine takdiminin vâcib olduğu yerler nelerdir? Sebepleri nelerdir?", "en": "Where must the mubtadaʾ precede the khabar, and why?"},
  "a": {"tr": "Dört yerde: mübtedâ sadr-ı kelâm olan bir şeyi tazammun ettiğinde, sadâretini korumak için (مَنْ أَبُوكَ); ikisi de ma'rife olduğunda, karışıklığı def için (زَيْدٌ الْمُنْطَلِقُ); ikisi de tahsiste müsâvî olduğunda (أَفْضَلُ مِنْكَ أَفْضَلُ مِنِّي); haber mübtedâ için fiil olduğunda, mübtedâ fâile (زَيْدٌ قَامَ) veya tesniye ve cem'de bedele (الزَّيْدَانِ قَامَا، الزَّيْدُونَ قَامُوا) karışmasın diye.", "en": "In four: when the mubtadaʾ contains a word that must open the speech (مَنْ أَبُوكَ); when both are definite, to avoid confusion (زَيْدٌ الْمُنْطَلِقُ); when both are equal in particularity (أَفْضَلُ مِنْكَ أَفْضَلُ مِنِّي); when the khabar is a verb, lest the mubtadaʾ be taken for the doer (زَيْدٌ قَامَ) or, in the dual and plural, for a badal (الزَّيْدَانِ قَامَا، الزَّيْدُونَ قَامُوا)."},
  "ar": ["زَيْدٌ الْمُنْطَلِقُ", "أَفْضَلُ مِنْكَ أَفْضَلُ مِنِّي"], "notes": ["taqdim-al-musnad-ilayh", "mubtada-khabar"]},
 {"n": 74, "q": {"tr": "Haberin mübtedâ üzerine takdiminin vâcib olduğu yerler nelerdir? Sebepleri nelerdir?", "en": "Where must the khabar precede the mubtadaʾ, and why?"},
  "a": {"tr": "Dört yerde: haber sadr-ı kelâm olan bir şeyi tazammun ettiğinde (أَيْنَ زَيْدٌ); nekre mübtedânın mübtedâlığını sahih kılan haber olduğunda, nekreyi tahsis için (فِي الدَّارِ رَجُلٌ); mübtedâda haberin müteallakına râci zamir olduğunda, izmâr kable'z-zikr lâzım gelmesin diye (عَلَى التَّمْرَةِ مِثْلُهَا زُبْدًا); haber أَنَّ'den haber olduğunda, إِنَّ-i meksûreye karışmasın diye (عِنْدِي أَنَّكَ قَائِمٌ).", "en": "In four: when the khabar contains a word that must open the speech (أَيْنَ زَيْدٌ); when it is what makes an indefinite mubtadaʾ possible (فِي الدَّارِ رَجُلٌ); when the mubtadaʾ holds a pronoun returning to something in the khabar (عَلَى التَّمْرَةِ مِثْلُهَا زُبْدًا); when the mubtadaʾ is a clause with أَنَّ, lest it be taken for kasra-إِنَّ (عِنْدِي أَنَّكَ قَائِمٌ)."},
  "ar": ["عَلَى التَّمْرَةِ مِثْلُهَا زُبْدًا", "عِنْدِي أَنَّكَ قَائِمٌ"], "notes": ["taqdim-al-musnad", "mubtada-khabar"]},
 {"n": 75, "q": {"tr": "Haberin taaddüdü câiz midir?", "en": "May the khabar be multiplied?"},
  "a": {"tr": "Atıflı veya atıfsız câizdir: زَيْدٌ عَالِمٌ عَاقِلٌ ve زَيْدٌ عَالِمٌ وَعَاقِلٌ.", "en": "Yes, with or without a conjunction: زَيْدٌ عَالِمٌ عَاقِلٌ and زَيْدٌ عَالِمٌ وَعَاقِلٌ."},
  "ar": ["زَيْدٌ عَالِمٌ عَاقِلٌ"], "notes": ["khabar-al-mubtada-wa-ahkamuh"]},
 {"n": 76, "q": {"tr": "Mübtedânın haberine fânın dühûlü ne zaman sahih olur?", "en": "When may the fāʾ enter the khabar of the mubtadaʾ?"},
  "a": {"tr": "Mübtedâ şart mânâsını tazammun ettiğinde: الَّذِي يَأْتِينِي فَلَهُ دِرْهَمٌ، الَّذِي فِي الدَّارِ فَلَهُ دِرْهَمٌ.", "en": "When the mubtadaʾ carries the sense of a condition: الَّذِي يَأْتِينِي فَلَهُ دِرْهَمٌ، الَّذِي فِي الدَّارِ فَلَهُ دِرْهَمٌ."},
  "ar": ["الَّذِي يَأْتِينِي فَلَهُ دِرْهَمٌ"], "notes": ["fa-khabar-mubtada", "al-fa-fi-khabar-al-mubtada"]},
 {"n": 77, "q": {"tr": "Mübtedânın hazfi kaç şekilde olur?", "en": "In how many ways is the mubtadaʾ dropped?"},
  "a": {"tr": "İki: karine kâim olduğunda cevâzen (الْهِلَالُ وَاللهِ, aslı هَذَا الْهِلَالُ وَاللهِ); ref' sebebiyle na't kesildiğinde vücûben (الْحَمْدُ لِلَّهِ أَهْلُ الْحَمْدِ, aslı هُوَ أَهْلُ الْحَمْدِ — أَهْلُ'ün ref' okunmasıyla lafzatullahtan sıfat olma ihtimali kesildiğinden هُوَ'nin hazfi vâcib olmuştur).", "en": "Two: optionally with a clue (الْهِلَالُ وَاللهِ, from هَذَا الْهِلَالُ وَاللهِ); necessarily when the rafʿ cuts off the adjective reading (الْحَمْدُ لِلَّهِ أَهْلُ الْحَمْدِ, from هُوَ أَهْلُ الْحَمْدِ — read in rafʿ, أَهْلُ can no longer describe the name of God, so هُوَ must be dropped)."},
  "ar": ["الْحَمْدُ لِلَّهِ أَهْلُ الْحَمْدِ"], "notes": ["hadhf-wa-taqdir", "al-mubtada-wa-nawah"]},
 {"n": 78, "q": {"tr": "Haberin hazfi kaç şekilde olur? Vücûben hazfi nerelerde olur?", "en": "In how many ways is the khabar dropped, and where is it dropped of necessity?"},
  "a": {"tr": "İki: karine kâim olup haber makamına bir şey kâim olmadığında cevâzen (خَرَجْتُ فَإِذَا السَّبُعُ — وَاقِفٌ hazfolunmuştur); karine kâim olup haber makamına başka bir şey kâim olduğunda vücûben, dört mevzide: mübtedâ لَوْلَا'dan sonra olup haberi umûmî fiillerden ise, لَوْلَا'nın cevabı haber makamına kâimdir (لَوْلَا زَيْدٌ لَهَلَكَ عَمْرٌو); mübtedâ fâiline veya mef'ûlüne muzâf masdar yahut ona muzâf ism-i tafdîl olup sonra hâl gelirse, hâl haber makamına kâimdir (ضَرْبِي زَيْدًا قَائِمًا); mübtedâ mukârenet mânâsını tazammun edip مَعَ mânâsına vâv ile üzerine bir şey atfolunursa, ma'tûf haber makamına kâimdir (كُلُّ رَجُلٍ وَضَيْعَتُهُ); mübtedâ muksemün bih olup haberi kasem ise, kasemin cevabı haber makamına kâimdir (لَعَمْرُكَ لَأَفْعَلَنَّ كَذَا).", "en": "Two: optionally with a clue when nothing stands in its place (خَرَجْتُ فَإِذَا السَّبُعُ, وَاقِفٌ dropped); necessarily when something else stands in its place, in four: after لَوْلَا with a general-verb khabar, its answer standing in (لَوْلَا زَيْدٌ لَهَلَكَ عَمْرٌو); a maṣdar annexed to its doer or object, or an ism tafḍīl annexed to one, followed by a ḥāl standing in (ضَرْبِي زَيْدًا قَائِمًا); a mubtadaʾ carrying accompaniment with something joined by a wāw meaning مَعَ, the joined word standing in (كُلُّ رَجُلٍ وَضَيْعَتُهُ); a mubtadaʾ sworn by with the oath as khabar, the oath's answer standing in (لَعَمْرُكَ لَأَفْعَلَنَّ كَذَا)."},
  "ar": ["لَوْلَا زَيْدٌ لَهَلَكَ عَمْرٌو", "ضَرْبِي زَيْدًا قَائِمًا", "كُلُّ رَجُلٍ وَضَيْعَتُهُ"], "notes": ["hadhf-wa-taqdir", "khabar-al-mubtada-wa-ahkamuh"]},
 {"n": 79, "q": {"tr": "إِنَّ bâbının haberinin ismi üzerine takdimi câiz midir?", "en": "May the khabar of إِنَّ precede its ism?"},
  "a": {"tr": "Haber zarf olup ismi ma'rife ise takdimi câizdir (إِنَّ إِلَيْنَا إِيَابَهُمْ); ismi nekre ise takdimi vâcibdir (إِنَّ مِنَ الْبَيَانِ لَسِحْرًا وَإِنَّ مِنَ الشِّعْرِ لَحِكْمَةً).", "en": "When the khabar is a ẓarf and the ism definite, it may (إِنَّ إِلَيْنَا إِيَابَهُمْ); when the ism is indefinite, it must (إِنَّ مِنَ الْبَيَانِ لَسِحْرًا وَإِنَّ مِنَ الشِّعْرِ لَحِكْمَةً)."},
  "ar": ["إِنَّ إِلَيْنَا إِيَابَهُمْ", "إِنَّ مِنَ الْبَيَانِ لَسِحْرًا"], "notes": ["inna-wa-akhawatuha", "al-marfuat-al-khamis-ila-al-tasi"]},
 {"n": 80, "q": {"tr": "لَيْسَ'ye benzeyen مَا ve لَا, لَيْسَ'ye nerede benzer?", "en": "In what do مَا and لَا resemble لَيْسَ?"},
  "a": {"tr": "İki yerde: nefiy mânâsı ifade etmekte ve mübtedâ ile haber üzerine dâhil olmakta.", "en": "In two: in conveying negation, and in entering upon a mubtadaʾ and khabar."},
  "ar": ["مَا زَيْدٌ قَائِمًا"], "notes": ["ma-la-mushabbaha", "al-marfuat-al-khamis-ila-al-tasi"]},
]
